jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };

  // ─── Audience gate ────────────────────────────────────────────────
  // Hard-coded allowlist — match the tool_configs audienceEmails so the
  // tile is also hidden for everyone else, but defensive in case the
  // bundle ever ships broadly.
  var ALLOWED = {
    "andrew_nemiroff@colpal.com": 1,
    "jared_lerner@colpal.com": 1,
  };
  var ident = (eli.tools && typeof eli.tools.userIdentity === "function")
    ? eli.tools.userIdentity() : {};
  var userEmail = String((ident && ident.email) || "").toLowerCase().trim();
  if (!ALLOWED[userEmail]) {
    eli.log.event("tool", "bd_template_tester_skip", { reason: "not_allowed", email: userEmail });
    return;
  }

  // ─── IDB storage — multi-test ─────────────────────────────────────
  // Each test is a named snapshot sourced from a template (e.g. user
  // creates "NDA basic" off the NDA template, makes edits, saves it
  // and can reload it later). Tests live in the "config" store under
  // short keys:
  //
  //   key: "bdtt_index"           → { active: <id>, tests: [{...}] }
  //   key: "bdtt_test_<id>"       → { id, content, savedAt }
  //
  // The id is a sanitized version of the user-entered label (e.g.
  // "NDA basic" → "nda_basic"). Short on purpose — user explicitly
  // asked for no long file names.
  //
  // IMPORTANT: STORE_CONFIG uses keyPath "key" (NOT "id" — see kernel
  // initFeatureDB). Putting a value without a top-level `key` field
  // throws.
  var INDEX_KEY = "bdtt_index";
  function _testKey(id) { return "bdtt_test_" + id; }

  function _slugifyId(label) {
    return String(label || "")
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "_")
      .replace(/^_+|_+$/g, "")
      .slice(0, 40)              // hard cap so keys stay short
      || ("test_" + Date.now().toString(36).slice(-6));
  }

  function _loadIndex() {
    if (!eli.storage || typeof eli.storage.get !== "function") return Promise.resolve({ active: null, tests: [] });
    return eli.storage.get("config", INDEX_KEY).then(function (row) {
      if (!row) return { active: null, tests: [] };
      return { active: row.active || null, tests: Array.isArray(row.tests) ? row.tests : [] };
    }).catch(function () { return { active: null, tests: [] }; });
  }
  function _saveIndex(idx) {
    return eli.storage.put("config", {
      key: INDEX_KEY,
      active: idx.active || null,
      tests: idx.tests || [],
      updatedAt: new Date().toISOString(),
    });
  }
  function _loadTestContent(id) {
    if (!id || !eli.storage || typeof eli.storage.get !== "function") return Promise.resolve(null);
    return eli.storage.get("config", _testKey(id)).catch(function () { return null; });
  }
  function _saveTestContent(id, captured) {
    if (!eli.storage || typeof eli.storage.put !== "function") {
      return Promise.reject(new Error("eli.storage unavailable"));
    }
    return eli.storage.put("config", {
      key: _testKey(id),
      id: id,
      content: JSON.stringify({
        savedDate: captured.savedDate,
        body: captured.body,
        sections: captured.sections,
      }),
      savedAt: new Date().toISOString(),
    });
  }
  // Wipes the per-test content row from IDB. Returns a promise that
  // resolves to true on success, false on failure. Logs the failure
  // (previously this swallowed errors silently, hiding the case where
  // delete didn't actually remove the row — user-reported regression).
  function _deleteTest(id) {
    if (!id) return Promise.resolve(true);
    var key = _testKey(id);
    return eli.storage.delete("config", key)
      .then(function () {
        // Verify the row is actually gone — guards against odd IDB
        // states (e.g. the keyPath shape mismatching the lookup key)
        // where delete silently no-ops.
        return eli.storage.get("config", key).then(function (row) {
          if (row) {
            eli.log.event("tool", "bd_template_tester_delete_residue", { key: key });
            return false;
          }
          return true;
        });
      })
      .catch(function (err) {
        eli.log.event("tool", "bd_template_tester_delete_failed", { key: key, msg: err && err.message });
        return false;
      });
  }

  // ─── Word-doc capture/load ────────────────────────────────────────
  // Mirrors build_draft's _captureActiveDocAsTemplate + _loadTemplateToWord.
  // We can't directly reuse them (build_draft is its own bundle and those
  // helpers aren't on window), so we duplicate the minimal capture+load
  // logic here. Body OOXML + per-section H/F captures = full template
  // fidelity.
  function _captureActiveDoc() {
    return eli.host.runRaw("bd_template_tester:capture_body", function (context) {
      var doc = context.document;
      var bodyOoxml = doc.body.getOoxml();
      var sections = doc.sections;
      sections.load("items");
      return context.sync().then(function () {
        return { body: bodyOoxml.value, sectionCount: sections.items.length };
      });
    }).then(function (state) {
      var sectionsData = [];
      var chain = Promise.resolve();
      for (var i = 0; i < state.sectionCount; i++) {
        (function (idx) {
          chain = chain.then(function () {
            return eli.host.runRaw("bd_template_tester:capture_section_" + idx, function (context) {
              var sections = context.document.sections;
              sections.load("items");
              return context.sync().then(function () {
                if (idx >= sections.items.length) return null;
                var sec = sections.items[idx];
                var grabs = {
                  primaryH: sec.getHeader("Primary").getOoxml(),
                  firstPageH: sec.getHeader("FirstPage").getOoxml(),
                  evenPagesH: sec.getHeader("EvenPages").getOoxml(),
                  primaryF: sec.getFooter("Primary").getOoxml(),
                  firstPageF: sec.getFooter("FirstPage").getOoxml(),
                  evenPagesF: sec.getFooter("EvenPages").getOoxml(),
                };
                return context.sync().then(function () {
                  return {
                    index: idx,
                    headers: {
                      primary: grabs.primaryH.value || "",
                      firstPage: grabs.firstPageH.value || "",
                      evenPages: grabs.evenPagesH.value || "",
                    },
                    footers: {
                      primary: grabs.primaryF.value || "",
                      firstPage: grabs.firstPageF.value || "",
                      evenPages: grabs.evenPagesF.value || "",
                    },
                  };
                });
              });
            }).then(function (data) { if (data) sectionsData.push(data); });
          });
        })(i);
      }
      return chain.then(function () {
        return { body: state.body, sections: sectionsData, savedDate: new Date().toISOString() };
      });
    });
  }

  // Load a template (JSON content string) into the active doc. Mirrors
  // build_draft's _loadTemplateToWord — body OOXML insert + per-section
  // header/footer inserts + font normalization.
  function _loadDocFromContent(contentString) {
    var parsed = null;
    try { parsed = JSON.parse(contentString); } catch (e) {
      return Promise.reject(new Error("Invalid template content (not JSON)"));
    }
    if (!parsed || !parsed.body) {
      return Promise.reject(new Error("Template has no body OOXML"));
    }
    return eli.host.runRaw("bd_template_tester:load_body", function (context) {
      var body = context.document.body;
      body.insertOoxml(parsed.body, Word.InsertLocation.replace);
      body.font.name = "Times New Roman";
      body.font.size = 11;
      var tables = body.tables;
      tables.load("items");
      var sections = context.document.sections;
      sections.load("items");
      return context.sync().then(function () {
        for (var ti = 0; ti < tables.items.length; ti++) {
          tables.items[ti].getRange().font.name = "Times New Roman";
        }
        return context.sync().then(function () { return sections.items.length; });
      });
    }).then(function (sectionCount) {
      if (!parsed.sections || !parsed.sections.length) return null;
      var chain = Promise.resolve();
      parsed.sections.forEach(function (secData, idx) {
        chain = chain.then(function () {
          return eli.host.runRaw("bd_template_tester:load_section_" + idx, function (context) {
            var sections = context.document.sections;
            sections.load("items");
            return context.sync().then(function () {
              if (idx >= sections.items.length) return;
              var sec = sections.items[idx];
              var hdrs = secData.headers || {};
              var ftrs = secData.footers || {};
              if (hdrs.primary) sec.getHeader("Primary").insertOoxml(hdrs.primary, Word.InsertLocation.replace);
              if (hdrs.firstPage) sec.getHeader("FirstPage").insertOoxml(hdrs.firstPage, Word.InsertLocation.replace);
              if (hdrs.evenPages) sec.getHeader("EvenPages").insertOoxml(hdrs.evenPages, Word.InsertLocation.replace);
              if (ftrs.primary) sec.getFooter("Primary").insertOoxml(ftrs.primary, Word.InsertLocation.replace);
              if (ftrs.firstPage) sec.getFooter("FirstPage").insertOoxml(ftrs.firstPage, Word.InsertLocation.replace);
              if (ftrs.evenPages) sec.getFooter("EvenPages").insertOoxml(ftrs.evenPages, Word.InsertLocation.replace);
              return context.sync();
            });
          });
        });
      });
      return chain;
    });
  }

  // ─── Overlay state ────────────────────────────────────────────────
  // saveState: "saved" | "unsaved" — reflects whether the in-doc state
  // matches the persisted content for the ACTIVE test. Resets to
  // "unsaved" after Reload (user must save again if they want the
  // next reload to include subsequent edits) and on Switch Test.
  var saveState = "unsaved";
  var _bdttIndex = null;       // cached {active, tests}; refreshed per open
  var _bdttTemplates = null;   // cached bd_templates rows; refreshed per open
  // Advanced section open/closed — Restore + Overwrite both live in
  // the same accordion, defaulting to closed. Session-local; resets
  // to false when the overlay re-opens.
  var _bdttAdvancedOpen = false;
  // After a fresh Resume/Create/Restore loads a template into the doc,
  // collapse the switcher / + New / 🗑 row so the active view is just
  // about the test we just loaded. Resets to false on overlay close,
  // so the next reopen shows the full chrome. The test label appears
  // as a plain heading in the collapsed state.
  var _bdttHeaderCollapsed = false;

  // ─── Overlay DOM (one in flight at a time) ────────────────────────
  function _openOverlay() {
    _closeOverlay();
    var ov = document.createElement("div");
    ov.id = "_bdtt_overlay";
    ov.style.cssText = [
      "position:fixed",
      "top:80px",
      "right:24px",
      "width:360px",
      "max-height:80vh",
      "z-index:99998",
      "background:#fff",
      "border:1px solid #cbd5e1",
      "box-shadow:0 12px 36px rgba(15,23,42,0.28)",
      "font-family:Inter,'Segoe UI',system-ui,sans-serif",
      "display:flex",
      "flex-direction:column",
      "overflow:hidden",
    ].join(";") + ";";
    ov.innerHTML =
      '<div id="_bdtt_header" style="padding:11px 14px;background:linear-gradient(135deg,#1e3a8a,#1565c0);color:#fff;display:flex;align-items:center;justify-content:space-between;gap:8px;cursor:move;user-select:none;">' +
        '<div style="display:flex;align-items:center;gap:8px;min-width:0;flex:1;">' +
          '<span style="font-size:14px;line-height:1;">🧪</span>' +
          '<span style="font-size:13px;font-weight:800;letter-spacing:0.02em;white-space:nowrap;">Template Tester</span>' +
        '</div>' +
        '<button id="_bdtt_close" type="button" style="background:rgba(255,255,255,0.18);border:1px solid rgba(255,255,255,0.4);color:#fff;padding:3px 9px;font-size:10px;font-weight:700;cursor:pointer;border-radius:0;line-height:1.2;">✕</button>' +
      '</div>' +
      // Tab strip — sticky between header and scrollable content.
      '<div id="_bdtt_tabs" style="display:flex;border-bottom:1px solid #cbd5e1;background:#f8fafc;flex:0 0 auto;"></div>' +
      // Tab content area — scrollable, paddings live here so the tab
      // bar above stays flush with the chrome.
      '<div id="_bdtt_body" style="padding:14px;display:flex;flex-direction:column;gap:10px;overflow-y:auto;flex:1 1 auto;"></div>';
    document.body.appendChild(ov);

    var headerEl = document.getElementById("_bdtt_header");
    if (typeof window._eliMakeDraggable === "function" && headerEl) {
      try { window._eliMakeDraggable(ov, headerEl); } catch (_) {}
    }
    // Bottom-right resize grip (kernel helper). Appends a ._eli3_dialog_resize_grip
    // div positioned absolute, mousedown-driven width/height drag with
    // 320×240 min, viewport−20 max. Our overlay's flex-column layout
    // means the scrollable tab body expands to fill the new height
    // automatically — no per-tab adjustments needed.
    if (typeof window._eliMakeResizable === "function") {
      try { window._eliMakeResizable(ov); } catch (_) {}
    }
    document.getElementById("_bdtt_close").onclick = _closeOverlay;

    // Paint tabs + initial body
    _renderTabs();
    _renderOverlayBody();
  }

  // Tab bar — two tabs: Test (current functionality) and Scan (new,
  // shows {{DEF}} tags found in the active doc with copy helpers).
  // Active tab tracked in _bdttTab (in-memory only; resets to "test"
  // on each fresh overlay open).
  var _bdttTab = "test";
  function _renderTabs() {
    var tabs = document.getElementById("_bdtt_tabs");
    if (!tabs) return;
    var defs = [
      { id: "test", label: "Test" },
      { id: "scan", label: "Scan" },
    ];
    tabs.innerHTML = defs.map(function (t) {
      var active = (t.id === _bdttTab);
      var style = [
        "flex:1",
        "padding:9px 10px",
        "font-size:11px",
        "font-weight:800",
        "letter-spacing:0.08em",
        "text-transform:uppercase",
        "background:" + (active ? "#fff" : "transparent"),
        "color:" + (active ? "#0f172a" : "#64748b"),
        "border:none",
        "border-bottom:" + (active ? "2px solid #1565c0" : "2px solid transparent"),
        "cursor:pointer",
        "font-family:inherit",
      ].join(";");
      return '<button type="button" data-bdtt-tab="' + t.id + '" style="' + style + '">' + _esc(t.label) + '</button>';
    }).join("");
    tabs.querySelectorAll("[data-bdtt-tab]").forEach(function (btn) {
      btn.onclick = function () {
        var id = btn.getAttribute("data-bdtt-tab");
        if (id === _bdttTab) return;
        _bdttTab = id;
        _renderTabs();
        _renderOverlayBody();
      };
    });
  }
  function _closeOverlay() {
    var existing = document.getElementById("_bdtt_overlay");
    if (existing && existing.parentNode) existing.parentNode.removeChild(existing);
    // Clear cached scan results so reopening the overlay re-scans
    // against the current doc — stale defs after an edit would be
    // worse than just running the scan again.
    _bdttScanDefs = null;
    _bdttScanReport = null;
    // Drop per-card pill selections too — defaults to first/second
    // option on next open is the expected fresh-start behavior.
    _bdttCardSelections = {};
    // Reset to Test tab so reopen starts in the primary workflow,
    // and re-collapse the Template Tools accordion. Also un-collapse
    // the active-view header so the next overlay open shows the
    // switcher / + New / 🗑 controls again.
    _bdttTab = "test";
    _bdttAdvancedOpen = false;
    _bdttHeaderCollapsed = false;
  }

  // Render the body of an already-mounted overlay. Pulled out so the
  // "switch test", "create new test", "delete test" actions can re-paint
  // without rebuilding the chrome (header + draggable wiring).
  //
  // Also enumerates which tests have saved content (one config-store
  // scan, then cached on _bdttSavedSet) so both views can mark
  // resumable tests with a 💾 indicator without N extra IDB reads.
  var _bdttSavedSet = null;
  function _renderOverlayBody() {
    var body = document.getElementById("_bdtt_body");
    if (!body) return;
    if (_bdttTab === "scan") { _renderScanTab(body); return; }
    Promise.all([_loadIndex(), _loadTemplates(), _loadSavedSet()]).then(function (results) {
      _bdttIndex = results[0];
      _bdttTemplates = results[1];
      _bdttSavedSet = results[2];
      // Clean up any orphan content rows (failed delete residue, stale
      // pre-refactor rows) using the freshly-loaded index. Background
      // — doesn't block the render.
      _sweepOrphans(_bdttIndex, _bdttSavedSet);
      if (!_bdttIndex.tests.length || !_bdttIndex.active) {
        // First-time / no-active state: ask user to create their first test.
        _renderPicker(body);
      } else {
        _renderActive(body);
      }
    }).catch(function (err) {
      body.innerHTML = '<div style="color:#b91c1c;font-size:12px;">Failed to load: ' + _esc(err && err.message || "unknown") + '</div>';
    });
  }
  function _loadSavedSet() {
    if (!eli.storage || typeof eli.storage.getAll !== "function") return Promise.resolve({});
    return eli.storage.getAll("config").then(function (rows) {
      var set = {};
      (rows || []).forEach(function (r) {
        if (!r || !r.key) return;
        if (String(r.key).indexOf("bdtt_test_") !== 0) return;
        if (!r.content) return;
        set[r.key.slice("bdtt_test_".length)] = true;
      });
      return set;
    }).catch(function () { return {}; });
  }

  // Opportunistic orphan sweep: every bdtt_test_<id> IDB row whose
  // <id> isn't in the current index is residue from a previous failed
  // delete (or stale data from before the multi-test refactor).
  // Called from _renderOverlayBody AFTER both index and saved-set are
  // freshly loaded — running it inside _loadSavedSet races with the
  // parallel _loadIndex and could nuke a just-created test.
  function _sweepOrphans(idx, savedSet) {
    if (!idx || !Array.isArray(idx.tests)) return;
    var knownIds = {};
    idx.tests.forEach(function (t) { if (t && t.id) knownIds[t.id] = true; });
    Object.keys(savedSet || {}).forEach(function (id) {
      if (!knownIds[id]) {
        eli.storage.delete("config", "bdtt_test_" + id).catch(function () {});
        delete savedSet[id];
        eli.log.event("tool", "bd_template_tester_orphan_swept", { id: id });
      }
    });
  }
  function _testHasSaved(id) {
    return !!(_bdttSavedSet && _bdttSavedSet[id]);
  }

  function _renderPicker(body) {
    var hasTests = !!(_bdttIndex.tests && _bdttIndex.tests.length);
    // The picker is now the explicit "what do you want to do" hub.
    // Two sections: existing tests (with smart Open = switch ± reload)
    // on top, create-new below. When there are no tests, only the
    // create section renders.
    var existingHtml = hasTests
      ? '<div style="display:flex;flex-direction:column;gap:6px;border:1px solid #cbd5e1;background:#f8fafc;padding:10px 12px;">' +
          '<div style="font-size:10px;font-weight:900;color:#0f172a;letter-spacing:0.1em;text-transform:uppercase;">🔄 Existing Tests</div>' +
          '<div style="font-size:10px;color:#64748b;line-height:1.4;">' +
            'Picking a test with <strong>💾</strong> reloads its saved draft into the doc and opens Step 1. ' +
            'Tests with no save just switch active.' +
          '</div>' +
          '<select id="_bdtt_open_pick" style="width:100%;padding:7px 8px;font-size:12px;font-family:inherit;border:1px solid #cbd5e1;border-radius:0;background:#fff;">' +
            '<option value="">— pick existing test —</option>' +
            _bdttIndex.tests.map(function (t) {
              var prefix = _testHasSaved(t.id) ? "💾 " : "";
              return '<option value="' + _esc(t.id) + '">' + prefix + _esc(t.label) + '</option>';
            }).join("") +
          '</select>' +
          '<button id="_bdtt_open_btn" class="btn-platinum" type="button" style="padding:8px 10px;font-size:11px;width:100%;border-radius:0;" disabled>Open Test</button>' +
        '</div>'
      : '';
    var heading = hasTests
      ? '<div style="font-size:11px;color:#0f172a;font-weight:700;">What would you like to do?</div>'
      : '<div style="font-size:11px;color:#0f172a;font-weight:700;">Create your first test:</div>';
    body.innerHTML =
      heading +
      existingHtml +
      '<div style="display:flex;flex-direction:column;gap:6px;border:1px solid #cbd5e1;background:#fff;padding:10px 12px;">' +
        '<div style="font-size:10px;font-weight:900;color:#0f172a;letter-spacing:0.1em;text-transform:uppercase;">🆕 Create New Test</div>' +
        '<label style="font-size:10px;color:#475569;font-weight:600;letter-spacing:0.04em;">TEST NAME</label>' +
        '<input id="_bdtt_new_name" type="text" placeholder="e.g. NDA basic" style="width:100%;padding:7px 8px;font-size:12px;font-family:inherit;border:1px solid #cbd5e1;border-radius:0;background:#fff;" />' +
        '<label style="font-size:10px;color:#475569;font-weight:600;letter-spacing:0.04em;">SOURCE TEMPLATE</label>' +
        '<select id="_bdtt_new_template" style="width:100%;padding:7px 8px;font-size:12px;font-family:inherit;border:1px solid #cbd5e1;border-radius:0;background:#fff;">' +
          _templateOptionsHtml() +
        '</select>' +
        '<button id="_bdtt_new_create" class="btn-platinum" type="button" style="padding:8px 10px;font-size:11px;width:100%;border-radius:0;" disabled>➕ Create Test</button>' +
      '</div>';

    // Wire the smart Open button — switches active, and if the picked
    // test has a saved draft, ALSO reloads its content into the doc and
    // dispatches to Step 1 (same path as Reload Draft). If it has no
    // saved draft, it just switches and lands on the active view.
    var openSel = document.getElementById("_bdtt_open_pick");
    var openBtn = document.getElementById("_bdtt_open_btn");
    function _refreshOpenBtn() {
      if (!openBtn || !openSel) return;
      var id = openSel.value;
      if (!id) {
        openBtn.disabled = true;
        openBtn.textContent = "Open Test";
        return;
      }
      openBtn.disabled = false;
      openBtn.textContent = _testHasSaved(id) ? "▶️ Resume Saved Draft" : "→ Switch to Test";
    }
    if (openSel) openSel.onchange = _refreshOpenBtn;
    if (openBtn) openBtn.onclick = function () {
      if (!openSel || !openSel.value) return;
      var pickedId = openSel.value;
      var hasSave = _testHasSaved(pickedId);
      _bdttIndex.active = pickedId;
      saveState = hasSave ? "saved" : "unsaved";
      _saveIndex(_bdttIndex).then(function () {
        if (!hasSave) {
          // No saved content — just switch and let the user decide.
          _renderOverlayBody();
          return;
        }
        // Resume: reload the saved draft into the doc + go to Step 1.
        openBtn.disabled = true;
        openBtn.textContent = "⏳ Resuming…";
        _toast("⏳ Reloading saved draft…", "info");
        _loadTestContent(pickedId).then(function (row) {
          if (!row || !row.content) {
            _toast("Saved content missing — switched only.", "warn");
            _renderOverlayBody();
            return;
          }
          return _loadDocFromContent(row.content).then(function () {
            _toast("✅ Resumed — Step 1 opening…", "ok");
            // Collapse the switcher row — user just made an explicit
            // choice to be on THIS test; keep the view focused on it.
            // Reverts on overlay close so the next reopen is full chrome.
            _bdttHeaderCollapsed = true;
            _renderOverlayBody();
            setTimeout(function () {
              try {
                var landed = false;
                try { landed = eli.dispatch("build_draft", "logic") === true; }
                catch (_inner) { landed = false; }
                if (!landed) eli.dispatch("tile", "app_build_draft");
              } catch (e) {
                eli.log.event("tool", "bd_template_tester_resume_step1_failed", { msg: e && e.message });
              }
            }, 300);
          });
        }).catch(function (err) {
          eli.log.event("tool", "bd_template_tester_resume_failed", { msg: err && err.message });
          _toast("Resume failed: " + (err && err.message || "unknown"), "err");
          _renderOverlayBody();
        });
      });
    };

    // Wire create flow
    var nameEl = document.getElementById("_bdtt_new_name");
    var tplEl  = document.getElementById("_bdtt_new_template");
    var btn    = document.getElementById("_bdtt_new_create");
    function _refreshCreateBtn() {
      btn.disabled = !(nameEl.value.trim() && tplEl.value);
    }
    nameEl.oninput = _refreshCreateBtn;
    tplEl.onchange = _refreshCreateBtn;
    btn.onclick = function () { _onCreateNewTest(nameEl.value.trim(), tplEl.value); };
  }

  function _renderActive(body) {
    var active = _bdttIndex.tests.find(function (t) { return t.id === _bdttIndex.active; });
    if (!active) {
      // Active id pointed to a missing test — drop it and re-render picker.
      _bdttIndex.active = null;
      _saveIndex(_bdttIndex).then(_renderOverlayBody);
      return;
    }
    var sourceLabel = active.sourceTemplateName || active.sourceTemplateId || "(template gone)";
    // Two header modes:
    //   • Collapsed: just the test label as a heading — set right after
    //     Resume/Create/Restore so the user focuses on the loaded
    //     template, not the meta-controls. Reverts on overlay reopen.
    //   • Full: the switcher dropdown + + New + 🗑 — for switching
    //     between tests or starting fresh.
    var headerHtml = _bdttHeaderCollapsed
      ? '<div style="display:flex;align-items:center;gap:8px;">' +
          '<span style="font-size:14px;line-height:1;">🧪</span>' +
          '<div style="font-size:13px;font-weight:800;color:#0f172a;letter-spacing:0.02em;flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + _esc(active.label) + '</div>' +
        '</div>'
      : '<div style="display:flex;gap:6px;align-items:center;">' +
          '<select id="_bdtt_switch_pick" style="flex:1;padding:6px 8px;font-size:11px;font-family:inherit;border:1px solid #cbd5e1;border-radius:0;background:#fff;">' +
            _bdttIndex.tests.map(function (t) {
              var sel = (t.id === _bdttIndex.active) ? ' selected' : '';
              var prefix = _testHasSaved(t.id) ? "💾 " : "";
              return '<option value="' + _esc(t.id) + '"' + sel + '>' + prefix + _esc(t.label) + '</option>';
            }).join("") +
          '</select>' +
          '<button id="_bdtt_new_test" type="button" title="Create a new test" style="padding:6px 10px;font-size:11px;font-weight:800;background:#f1f5f9;border:1px solid #cbd5e1;color:#0f172a;cursor:pointer;">+ New</button>' +
          '<button id="_bdtt_del_test" type="button" title="Delete this test" style="padding:6px 8px;font-size:13px;background:#fef2f2;border:1px solid #fecaca;color:#b91c1c;cursor:pointer;line-height:1;">🗑</button>' +
        '</div>';
    body.innerHTML =
      headerHtml +
      '<div style="font-size:10px;color:#64748b;">Source: <strong style="color:#0f172a;font-weight:600;">' + _esc(sourceLabel) + '</strong></div>' +

      // Status pill
      '<div id="_bdtt_status" style="font-size:10px;font-weight:800;letter-spacing:0.1em;text-transform:uppercase;padding:5px 8px;border:1px solid #cbd5e1;background:#f1f5f9;color:#475569;display:inline-block;align-self:flex-start;">— loading —</div>' +

      // Action buttons
      '<div style="display:flex;flex-direction:column;gap:6px;">' +
        '<button id="_bdtt_temp_save" class="btn-platinum" type="button" style="padding:8px 10px;font-size:11px;width:100%;border-radius:0;">💾 Temp Save Draft</button>' +
        '<button id="_bdtt_reload" class="btn-platinum" type="button" style="padding:8px 10px;font-size:11px;width:100%;border-radius:0;">🔄 Reload Draft</button>' +
      '</div>' +

      '<div style="height:1px;background:#e2e8f0;margin:4px 0;"></div>' +

      // ─── Template Tools (collapsible, closed by default) ─────────
      // Houses both Restore-from-Source and Overwrite-a-Real-Template.
      // Both are "danger-adjacent" — they reach outside the test
      // sandbox to touch the source bd_templates row or replace the
      // live doc body. Defaulting closed keeps them out of the
      // muscle-memory path for Temp Save / Reload, which is the
      // primary loop.
      '<button id="_bdtt_adv_toggle" type="button" style="display:flex;align-items:center;justify-content:space-between;gap:6px;width:100%;padding:7px 10px;font-size:10px;font-weight:900;letter-spacing:0.12em;text-transform:uppercase;background:#f1f5f9;border:1px solid #cbd5e1;color:#0f172a;cursor:pointer;border-radius:0;">' +
        '<span>🛠 Template Tools</span>' +
        '<span id="_bdtt_adv_chevron" style="font-size:9px;color:#64748b;">' + (_bdttAdvancedOpen ? "▼" : "▶") + '</span>' +
      '</button>' +
      '<div id="_bdtt_adv_content" style="' + (_bdttAdvancedOpen ? "" : "display:none;") + 'flex-direction:column;gap:10px;padding:10px 12px;border:1px solid #cbd5e1;border-top:none;background:#fff;">' +
        // Restore from source
        '<div style="display:flex;flex-direction:column;gap:6px;">' +
          '<div style="font-size:10px;font-weight:800;color:#475569;letter-spacing:0.08em;text-transform:uppercase;">Restore from Source Template</div>' +
          '<button id="_bdtt_restore" class="btn-platinum" type="button" style="padding:8px 10px;font-size:11px;width:100%;border-radius:0;">🌱 Restore from Source Template</button>' +
          '<div style="font-size:10px;color:#64748b;line-height:1.45;font-style:italic;">Reload the original <strong>' + _esc(sourceLabel) + '</strong> content into the doc. Replaces your test\'s temp save with a fresh baseline.</div>' +
        '</div>' +
        '<div style="height:1px;background:#e2e8f0;"></div>' +
        // Overwrite a real template
        '<div style="display:flex;flex-direction:column;gap:6px;">' +
          '<div style="font-size:10px;font-weight:800;color:#475569;letter-spacing:0.08em;text-transform:uppercase;">Overwrite a Real Template</div>' +
          '<select id="_bdtt_template_pick" style="width:100%;padding:7px 8px;font-size:12px;font-family:inherit;border:1px solid #cbd5e1;border-radius:0;background:#fff;">' +
            _templateOptionsHtml() +
          '</select>' +
          '<button id="_bdtt_overwrite" class="btn-platinum" type="button" style="padding:8px 10px;font-size:11px;width:100%;border-radius:0;" disabled>📥 Overwrite Selected Template</button>' +
          '<div style="font-size:10px;color:#64748b;line-height:1.45;font-style:italic;">Active doc replaces the selected template after confirmation. The template id, name, agreement type, and party are preserved.</div>' +
        '</div>' +
      '</div>';

    // Wire switcher / new / delete — only when the header isn't
    // collapsed (those elements don't exist in the collapsed state).
    var switchEl = document.getElementById("_bdtt_switch_pick");
    if (switchEl) switchEl.onchange = function (e) {
      _bdttIndex.active = e.target.value;
      saveState = "unsaved";
      _saveIndex(_bdttIndex).then(_renderOverlayBody);
    };
    var newBtn = document.getElementById("_bdtt_new_test");
    if (newBtn) newBtn.onclick = function () {
      // Drop active so the picker renders.
      _bdttIndex.active = null;
      _renderPicker(body);
    };
    var delBtn = document.getElementById("_bdtt_del_test");
    if (delBtn) delBtn.onclick = function () {
      _onDeleteActiveTest(active);
    };

    // Status reflects the active test's stored content (if any).
    // Resume now lives on the picker view — the active view stays
    // clean: status pill + Temp Save / Reload buttons are enough.
    _loadTestContent(active.id).then(function (row) {
      if (row && row.content) {
        saveState = "saved";
        var savedTs = row.savedAt ? new Date(row.savedAt) : null;
        _paintStatus("Saved · " + (savedTs ? savedTs.toLocaleTimeString() : ""));
      } else {
        saveState = "unsaved";
        _paintStatus("— no draft saved yet —");
      }
    });

    document.getElementById("_bdtt_temp_save").onclick = _onTempSave;
    document.getElementById("_bdtt_reload").onclick = _onReload;
    document.getElementById("_bdtt_overwrite").onclick = _onOverwrite;
    var pickEl = document.getElementById("_bdtt_template_pick");
    pickEl.onchange = function () {
      document.getElementById("_bdtt_overwrite").disabled = !pickEl.value;
    };
    // Accordion toggle — show/hide the Restore + Overwrite group.
    var advToggle = document.getElementById("_bdtt_adv_toggle");
    var advContent = document.getElementById("_bdtt_adv_content");
    var advChevron = document.getElementById("_bdtt_adv_chevron");
    if (advToggle && advContent) {
      advToggle.onclick = function () {
        _bdttAdvancedOpen = !_bdttAdvancedOpen;
        advContent.style.display = _bdttAdvancedOpen ? "flex" : "none";
        if (advChevron) advChevron.textContent = _bdttAdvancedOpen ? "▼" : "▶";
      };
      // Make sure flex layout is honored when starting open.
      if (_bdttAdvancedOpen) advContent.style.display = "flex";
    }
    // Restore from Source Template
    document.getElementById("_bdtt_restore").onclick = function () {
      _onRestoreFromSource(active);
    };
  }

  function _paintStatus(text) {
    var el = document.getElementById("_bdtt_status");
    if (!el) return;
    el.textContent = text;
    if (saveState === "saved") {
      el.style.background = "#dcfce7";
      el.style.borderColor = "#86efac";
      el.style.color = "#166534";
    } else {
      el.style.background = "#fef3c7";
      el.style.borderColor = "#f59e0b";
      el.style.color = "#92400e";
    }
  }

  // Templates dropdown — fed by both the new-test picker and the
  // overwrite section. Filters out any rows whose ID looks like a
  // bdtt test artifact (defensive; tests live in `config`, not
  // `bd_templates`, so this should always be empty — but kept in
  // case someone manually saves a bdtt_ row to bd_templates).
  function _loadTemplates() {
    if (!eli.storage || typeof eli.storage.getAll !== "function") return Promise.resolve([]);
    return eli.storage.getAll("bd_templates").then(function (rows) {
      var list = (rows || []).filter(function (r) {
        if (!r || !r.id) return false;
        var id = String(r.id);
        if (id.charAt(0) === "_") return false;          // kernel meta
        if (id.indexOf("bdtt_") === 0) return false;     // tester artifact
        return true;
      });
      list.sort(function (a, b) {
        var an = String(a.name || a.id || "").toLowerCase();
        var bn = String(b.name || b.id || "").toLowerCase();
        return an.localeCompare(bn);
      });
      return list;
    }).catch(function () { return []; });
  }
  function _templateOptionsHtml() {
    var rows = _bdttTemplates || [];
    var html = '<option value="">— pick a template —</option>';
    rows.forEach(function (r) {
      var label = r.name || r.id;
      if (r.agreementType) label += " · " + r.agreementType;
      if (r.party) label += " · " + r.party;
      html += '<option value="' + _esc(r.id) + '">' + _esc(label) + '</option>';
    });
    return html;
  }

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function _toast(msg, kind) {
    if (typeof window.showToast === "function") window.showToast(msg, kind || "info");
  }

  // ─── New / delete test actions ────────────────────────────────────
  // Create flow: save the test entry, load the chosen template into the
  // active doc, then drop the user on Build Draft Step 1 (logic form).
  // This is the whole point of a "test" — you want to be working in the
  // template immediately, not staring at a confirmation toast.
  function _onCreateNewTest(label, sourceTemplateId) {
    if (!label) { _toast("Give the test a name.", "warn"); return; }
    if (!sourceTemplateId) { _toast("Pick a source template.", "warn"); return; }
    var id = _slugifyId(label);
    // Disambiguate if the id collides with an existing test.
    var existingIds = (_bdttIndex.tests || []).map(function (t) { return t.id; });
    var base = id, n = 2;
    while (existingIds.indexOf(id) !== -1) { id = base + "_" + n; n++; }
    var tpl = (_bdttTemplates || []).find(function (r) { return r.id === sourceTemplateId; });
    var entry = {
      id: id,
      label: label,
      sourceTemplateId: sourceTemplateId,
      sourceTemplateName: tpl ? (tpl.name || tpl.id) : sourceTemplateId,
      createdAt: new Date().toISOString(),
    };
    _bdttIndex.tests.push(entry);
    _bdttIndex.active = id;
    _saveIndex(_bdttIndex)
      .then(function () { return eli.storage.get("bd_templates", sourceTemplateId); })
      .then(function (row) {
        if (!row || !row.content) {
          throw new Error("Source template has no content (id: " + sourceTemplateId + ")");
        }
        _toast("⏳ Loading " + (tpl && tpl.name || sourceTemplateId) + " into doc…", "info");
        return _loadDocFromContent(row.content);
      })
      // Auto-baseline: snapshot the freshly-loaded template as the
      // test's first saved draft. Without this the user has to
      // remember to click Temp Save before making any edits — and if
      // they don't, Reload Draft has nothing to reload to. This gives
      // every test a known-good "back to the template" state from the
      // moment it's created. Failure here doesn't block the rest of
      // the flow; user can still manually Temp Save later.
      .then(function () {
        return _captureActiveDoc()
          .then(function (captured) { return _saveTestContent(id, captured); })
          .then(function () {
            if (!_bdttSavedSet) _bdttSavedSet = {};
            _bdttSavedSet[id] = true;
            saveState = "saved";
          })
          .catch(function (err) {
            eli.log.event("tool", "bd_template_tester_create_baseline_save_failed", { msg: err && err.message });
            // Soft failure — user got the doc loaded, just missed the baseline.
          });
      })
      .then(function () {
        _toast("✅ Test ready (baseline saved) — Step 1 opening…", "ok");
        // Collapse the switcher row — fresh load, keep view focused on
        // the new test. Reverts on next overlay open.
        _bdttHeaderCollapsed = true;
        // Re-render overlay first so user sees the new active state,
        // then drop them on Step 1 of Build Draft. Same dispatch
        // pattern as _onReload — `build_draft/logic` lands directly
        // on the dropdown form; falls back to the tile entry if the
        // user is on an older build_draft.
        _renderOverlayBody();
        setTimeout(function () {
          try {
            var landed = false;
            try { landed = eli.dispatch("build_draft", "logic") === true; }
            catch (_inner) { landed = false; }
            if (!landed) eli.dispatch("tile", "app_build_draft");
          } catch (e) {
            eli.log.event("tool", "bd_template_tester_create_step1_failed", { msg: e && e.message });
          }
        }, 300);
      })
      .catch(function (err) {
        // Test entry already saved — user can pick a different template
        // manually via the Overwrite dropdown if they want. Surface the
        // failure so they know to do something.
        eli.log.event("tool", "bd_template_tester_create_load_failed", { msg: err && err.message });
        _toast("Test created but template load failed: " + (err && err.message || "unknown"), "err");
        _renderOverlayBody();
      });
  }
  function _onDeleteActiveTest(entry) {
    var confirmFn = (eli.ui && typeof eli.ui.confirm === "function")
      ? eli.ui.confirm.bind(eli.ui) : null;
    if (!confirmFn) { _toast("eli.ui.confirm unavailable.", "err"); return; }
    confirmFn({
      title: "Delete test?",
      message: "Removes <strong>" + _esc(entry.label) + "</strong> and its saved draft. Doesn't touch the source template.",
      confirmLabel: "Delete",
      cancelLabel: "Cancel",
      variant: "danger",
    }).then(function (ok) {
      if (!ok) return;
      _bdttIndex.tests = _bdttIndex.tests.filter(function (t) { return t.id !== entry.id; });
      // Promote the first remaining test to active so the user lands
      // somewhere useful; if none left, picker view will render.
      _bdttIndex.active = _bdttIndex.tests.length ? _bdttIndex.tests[0].id : null;
      if (_bdttSavedSet) delete _bdttSavedSet[entry.id];
      // Order matters: delete the IDB content row FIRST, then update the
      // index. If we reversed it and the IDB delete failed, the user
      // would have a "ghost" row in IDB with no index entry pointing
      // to it — an orphan that can't be reached via the UI to retry
      // the delete.
      Promise.all([_deleteTest(entry.id), _saveIndex(_bdttIndex)]).then(function (results) {
        var idbCleanOk = results[0] !== false;
        if (idbCleanOk) {
          _toast("Test deleted.", "ok");
        } else {
          _toast("Test removed from list, but IDB cleanup failed — check console.", "warn");
        }
        _renderOverlayBody();
      });
    });
  }

  // Restore the source template into the doc + re-baseline the test.
  // Equivalent to creating the test from scratch — wipes the user's
  // temp-saved state for this test and replaces it with a fresh snapshot
  // of the source template. Drops them on Step 1 the same way Create
  // and Reload do.
  function _onRestoreFromSource(active) {
    if (!active || !active.sourceTemplateId) {
      _toast("This test has no source template recorded.", "warn");
      return;
    }
    var confirmFn = (eli.ui && typeof eli.ui.confirm === "function")
      ? eli.ui.confirm.bind(eli.ui) : null;
    if (!confirmFn) { _toast("eli.ui.confirm unavailable.", "err"); return; }
    var sourceLabel = active.sourceTemplateName || active.sourceTemplateId;
    confirmFn({
      title: "Restore from source template?",
      message:
        "Replaces the current document with a fresh copy of <strong>" + _esc(sourceLabel) + "</strong>. " +
        "Your test\'s temp save is overwritten with this new baseline — any edits you made are lost.",
      confirmLabel: "Restore",
      cancelLabel: "Cancel",
      variant: "danger",
    }).then(function (ok) {
      if (!ok) return;
      var btn = document.getElementById("_bdtt_restore");
      if (btn) { btn.disabled = true; btn.textContent = "⏳ Restoring…"; }
      _toast("⏳ Loading source template…", "info");
      eli.storage.get("bd_templates", active.sourceTemplateId)
        .then(function (row) {
          if (!row || !row.content) throw new Error("Source template content missing");
          return _loadDocFromContent(row.content);
        })
        .then(function () {
          // Re-baseline: capture the freshly-loaded source as the test's
          // new temp save. Without this, Reload Draft would still pull
          // back the OLD pre-restore state — the opposite of what the
          // user just asked for.
          return _captureActiveDoc().then(function (captured) {
            return _saveTestContent(active.id, captured);
          });
        })
        .then(function () {
          saveState = "saved";
          if (!_bdttSavedSet) _bdttSavedSet = {};
          _bdttSavedSet[active.id] = true;
          _toast("✅ Restored from source — Step 1 opening…", "ok");
          // Collapse switcher row — user just restored, focus the view
          // on the test they just reset. Reverts on next overlay open.
          _bdttHeaderCollapsed = true;
          _renderOverlayBody();
          setTimeout(function () {
            try {
              var landed = false;
              try { landed = eli.dispatch("build_draft", "logic") === true; }
              catch (_inner) { landed = false; }
              if (!landed) eli.dispatch("tile", "app_build_draft");
            } catch (e) {
              eli.log.event("tool", "bd_template_tester_restore_step1_failed", { msg: e && e.message });
            }
          }, 300);
        })
        .catch(function (err) {
          eli.log.event("tool", "bd_template_tester_restore_failed", { msg: err && err.message });
          _toast("Restore failed: " + (err && err.message || "unknown"), "err");
          if (btn) { btn.disabled = false; btn.textContent = "🌱 Restore from Source Template"; }
        });
    });
  }

  // ─── Actions — Temp Save / Reload (act on the ACTIVE test) ────────
  function _activeId() {
    return _bdttIndex && _bdttIndex.active;
  }

  // Quick existence check: does the active doc contain ANY {{...}} tag?
  // Used by Temp Save + Overwrite to warn the user before they save a
  // doc that's not actually a template (very easy to do — e.g. they
  // loaded a draft into Word, all the {{}}s got replaced through Step 1,
  // they hit Temp Save expecting to snapshot the template but instead
  // they're snapshotting the filled draft).
  //
  // Wildcard "{{*}}" catches {{IF}}, {{DEF}}, {{KEY}}, etc. — any
  // template marker. Fail-open on error so a Word.run hiccup doesn't
  // block a legitimate save.
  function _docHasTemplateTags() {
    return eli.host.runRaw("bd_template_tester:tag_check", function (context) {
      var b = context.document.body;
      var search = b.search("\\{\\{*\\}\\}", { matchWildcards: true });
      search.load("items");
      return context.sync().then(function () {
        return search.items.length > 0;
      });
    }).catch(function () { return true; });
  }
  // Pop the warning confirm. Caller resolves true if the user wants to
  // proceed anyway, false if they cancelled.
  function _confirmEmptyTemplateSave(actionLabel) {
    var confirmFn = (eli.ui && typeof eli.ui.confirm === "function")
      ? eli.ui.confirm.bind(eli.ui) : null;
    if (!confirmFn) return Promise.resolve(true); // no UI primitive — fail-open
    return confirmFn({
      title: "No template tags found",
      message:
        "This document doesn't contain any <code>{{...}}</code> tags — it doesn't look like a template. " +
        "Are you sure you want to <strong>" + _esc(actionLabel) + "</strong> this as a template?",
      confirmLabel: actionLabel + " Anyway",
      cancelLabel: "Cancel",
      variant: "warn",
    });
  }

  function _onTempSave() {
    var id = _activeId();
    if (!id) { _toast("Pick or create a test first.", "warn"); return; }
    var btn = document.getElementById("_bdtt_temp_save");
    _docHasTemplateTags().then(function (hasTags) {
      if (hasTags) return true;
      return _confirmEmptyTemplateSave("Temp Save");
    }).then(function (proceed) {
      if (!proceed) {
        _toast("Save cancelled.", "info");
        return;
      }
      if (btn) { btn.disabled = true; btn.textContent = "⏳ Saving…"; }
      _toast("⏳ Capturing draft…", "info");
      _captureActiveDoc().then(function (captured) {
        return _saveTestContent(id, captured);
      }).then(function () {
        saveState = "saved";
        _paintStatus("Saved · " + new Date().toLocaleTimeString());
        _toast("✅ Draft saved", "ok");
        if (btn) { btn.disabled = false; btn.textContent = "💾 Temp Save Draft"; }
        // Mark the test as resumable in the cached saved-set so the
        // switcher 💾 indicator + the Resume CTA show up immediately on
        // the next re-render without another full IDB scan.
        if (!_bdttSavedSet) _bdttSavedSet = {};
        _bdttSavedSet[id] = true;
      }).catch(function (err) {
        eli.log.event("tool", "bd_template_tester_save_failed", { msg: err && err.message });
        _toast("Save failed: " + (err && err.message), "err");
        if (btn) { btn.disabled = false; btn.textContent = "💾 Temp Save Draft"; }
      });
    });
  }

  function _onReload() {
    var id = _activeId();
    if (!id) { _toast("Pick or create a test first.", "warn"); return; }
    var btn = document.getElementById("_bdtt_reload");
    if (btn) { btn.disabled = true; btn.textContent = "⏳ Reloading…"; }
    _loadTestContent(id).then(function (row) {
      if (!row || !row.content) {
        _toast("No saved draft yet — click Temp Save Draft first.", "warn");
        if (btn) { btn.disabled = false; btn.textContent = "🔄 Reload Draft"; }
        return null;
      }
      _toast("⏳ Reloading draft into doc…", "info");
      return _loadDocFromContent(row.content).then(function () {
        // Status flips to "unsaved" after a reload — the user about to
        // edit must re-save if they want the next reload to include
        // their changes.
        saveState = "unsaved";
        _paintStatus("Unsaved — edits will need a fresh Temp Save");
        _toast("✅ Draft reloaded", "ok");
        // Re-trigger Build Draft's Step 1 (logic form with dropdowns)
        // so the freshly-loaded doc gets re-scanned for OARS and the
        // dropdowns show up again. We dispatch into the "build_draft"
        // channel — `logic` lands directly on _renderLogicPanel, which
        // is the Step 1 view. The older tile dispatch went to the hub,
        // forcing the user through an extra click. Falls back to the
        // tile entrypoint when build_draft is too old to expose this
        // channel. Wrapped in setTimeout so the doc-load Word.run
        // scopes finish settling before the OARS scan starts.
        setTimeout(function () {
          try {
            if (eli.dispatch && typeof eli.dispatch === "function") {
              // The build_draft dispatch handlers return `true` on success;
              // eli.dispatch returns undefined for missing channels. Use
              // that to fall back to the tile entry (which lands on the
              // hub) when the user is on an older build_draft.
              var landed = false;
              try {
                landed = eli.dispatch("build_draft", "logic") === true;
              } catch (_inner) { landed = false; }
              if (!landed) eli.dispatch("tile", "app_build_draft");
            }
          } catch (e) {
            eli.log.event("tool", "bd_template_tester_step1_relaunch_failed", { msg: e && e.message });
          }
        }, 300);
      });
    }).catch(function (err) {
      eli.log.event("tool", "bd_template_tester_reload_failed", { msg: err && err.message });
      _toast("Reload failed: " + (err && err.message), "err");
    }).then(function () {
      if (btn) { btn.disabled = false; btn.textContent = "🔄 Reload Draft"; }
    });
  }

  function _onOverwrite() {
    var sel = document.getElementById("_bdtt_template_pick");
    if (!sel || !sel.value) { _toast("Pick a template first.", "warn"); return; }
    var templateId = sel.value;
    var templateLabel = sel.options[sel.selectedIndex].textContent;
    // Confirm via eli.ui.confirm (NOT native confirm — Script Lab
    // sandbox blocks confirm()).
    var confirmFn = (eli.ui && typeof eli.ui.confirm === "function")
      ? eli.ui.confirm.bind(eli.ui)
      : null;
    if (!confirmFn) { _toast("eli.ui.confirm unavailable.", "err"); return; }
    // Two-stage confirm. First check the doc actually looks like a
    // template — if not, warn the user BEFORE showing the dangerous
    // overwrite dialog. This prevents the "I clicked through both
    // confirms muscle-memory and now my real template is replaced
    // with an empty doc" foot-gun.
    _docHasTemplateTags().then(function (hasTags) {
      if (hasTags) return true;
      return _confirmEmptyTemplateSave("Overwrite");
    }).then(function (proceedFromTagCheck) {
      if (!proceedFromTagCheck) {
        _toast("Overwrite cancelled.", "info");
        return null;
      }
      return confirmFn({
        title: "Overwrite template?",
        message: "This will replace the saved template <strong>" + _esc(templateLabel) + "</strong> with the current active document. The template's id, name, agreement type, and party are preserved.",
        confirmLabel: "Overwrite",
        cancelLabel: "Cancel",
        variant: "danger",
      });
    }).then(function (ok) {
      if (!ok) return;
      var btn = document.getElementById("_bdtt_overwrite");
      if (btn) { btn.disabled = true; btn.textContent = "⏳ Overwriting…"; }
      eli.storage.get("bd_templates", templateId).then(function (existing) {
        if (!existing) throw new Error("Template not found in IDB: " + templateId);
        return _captureActiveDoc().then(function (captured) {
          var rec = Object.assign({}, existing, {
            content: JSON.stringify({
              agreementType: existing.agreementType,
              partyName: existing.party || "",
              savedDate: captured.savedDate,
              body: captured.body,
              sections: captured.sections,
            }),
            savedDate: new Date().toLocaleString(),
            timestamp: Date.now(),
          });
          return eli.storage.put("bd_templates", rec);
        });
      }).then(function () {
        _toast("✅ Template overwritten", "ok");
        if (btn) { btn.disabled = false; btn.textContent = "📥 Overwrite Selected Template"; }
        // Refresh the templates cache + repaint so the dropdown's
        // display label updates if it changed.
        _loadTemplates().then(function (rows) {
          _bdttTemplates = rows;
          var sel = document.getElementById("_bdtt_template_pick");
          if (sel) sel.innerHTML = _templateOptionsHtml();
          var ob = document.getElementById("_bdtt_overwrite");
          if (ob) ob.disabled = true;
        });
      }).catch(function (err) {
        eli.log.event("tool", "bd_template_tester_overwrite_failed", { msg: err && err.message });
        _toast("Overwrite failed: " + (err && err.message), "err");
        if (btn) { btn.disabled = false; btn.textContent = "📥 Overwrite Selected Template"; }
      });
    });
  }

  // ─── Scan tab — find {{DEF}} tags and copy as variable/IF/ELSEIF ──
  // Pure inspection panel: scans the body of the active doc, parses
  // every {{DEF:name=default|opt1,opt2|warning}} tag, and surfaces a
  // copy menu per def. Copy targets:
  //   • Variable → "{{NAME}}"                — drop where you want
  //                                            substitution
  //   • IF       → "{{IF:NAME==<opt1>}}"     — first option pre-filled
  //   • ELSEIF   → "{{ELSEIF:NAME==<opt2>}}" — second option (when
  //                                            present)
  //
  // Empty {{ENDIF}} / {{ELSE}} aren't surfaced — only defs. Text-input
  // defs (option string starting with `*`) suppress IF/ELSEIF since
  // there's no enumerated value to slot in.
  //
  // Cached `_bdttScanDefs` survives tab toggles within one overlay
  // session so flipping back to Scan doesn't re-Word.run unless the
  // user explicitly hits Re-scan. Cleared by _closeOverlay below.
  var _bdttScanDefs = null;
  var _bdttScanReport = null;  // {counts, ifRefs, orphans, defs}
  function _renderScanTab(body) {
    body.innerHTML =
      '<div style="font-size:11px;color:#0f172a;font-weight:700;">Scan the current document for template structure.</div>' +
      '<button id="_bdtt_scan_run" class="btn-platinum" type="button" style="padding:8px 10px;font-size:11px;width:100%;border-radius:0;">🔍 Scan Document</button>' +
      '<div id="_bdtt_scan_results"></div>' +
      // Add-DEF builder — always at the bottom of the Scan tab.
      // Inputs build a perfectly formatted {{DEF:NAME=default|opt1,opt2|warning}}
      // tag and copy it. Useful in tandem with the scan results:
      // see what DEFs exist, add a new one without typing the syntax
      // from scratch.
      '<div style="height:1px;background:#e2e8f0;margin:6px 0;"></div>' +
      '<div style="display:flex;flex-direction:column;gap:6px;border:1px solid #cbd5e1;background:#f8fafc;padding:10px 12px;">' +
        '<div style="font-size:10px;font-weight:900;color:#0f172a;letter-spacing:0.1em;text-transform:uppercase;">➕ Add New DEF</div>' +
        '<div style="font-size:10px;color:#64748b;line-height:1.4;">Builds a formatted <code style="font-family:monospace;">{{DEF}}</code> tag and copies it to the clipboard.</div>' +
        // Name
        '<label style="font-size:10px;color:#475569;font-weight:600;letter-spacing:0.04em;">NAME <span style="color:#94a3b8;font-weight:500;">(letters / digits / underscores — auto-uppercased)</span></label>' +
        '<input id="_bdtt_adddef_name" type="text" placeholder="e.g. PARTY_TYPE" style="width:100%;padding:7px 8px;font-size:12px;font-family:monospace;border:1px solid #cbd5e1;border-radius:0;background:#fff;text-transform:uppercase;" />' +
        // Type
        '<label style="font-size:10px;color:#475569;font-weight:600;letter-spacing:0.04em;">TYPE</label>' +
        '<div style="display:flex;gap:6px;">' +
          '<label style="flex:1;display:flex;align-items:center;gap:5px;font-size:11px;cursor:pointer;border:1px solid #cbd5e1;padding:5px 8px;background:#fff;">' +
            '<input type="radio" name="_bdtt_adddef_type" value="choice" checked style="margin:0;" /> Choice (dropdown)' +
          '</label>' +
          '<label style="flex:1;display:flex;align-items:center;gap:5px;font-size:11px;cursor:pointer;border:1px solid #cbd5e1;padding:5px 8px;background:#fff;">' +
            '<input type="radio" name="_bdtt_adddef_type" value="text" style="margin:0;" /> Text (free input)' +
          '</label>' +
        '</div>' +
        // Choices (visible when type=choice)
        '<div id="_bdtt_adddef_choice_block" style="display:flex;flex-direction:column;gap:6px;">' +
          '<label style="font-size:10px;color:#475569;font-weight:600;letter-spacing:0.04em;">CHOICES <span style="color:#94a3b8;font-weight:500;">(one per line — first is the default)</span></label>' +
          '<textarea id="_bdtt_adddef_choices" rows="4" placeholder="Buyer&#10;Seller&#10;Both" style="width:100%;padding:7px 8px;font-size:12px;font-family:inherit;border:1px solid #cbd5e1;border-radius:0;background:#fff;resize:vertical;"></textarea>' +
        '</div>' +
        // Placeholder (visible when type=text)
        '<div id="_bdtt_adddef_text_block" style="display:none;flex-direction:column;gap:6px;">' +
          '<label style="font-size:10px;color:#475569;font-weight:600;letter-spacing:0.04em;">PLACEHOLDER <span style="color:#94a3b8;font-weight:500;">(optional, shown as input hint)</span></label>' +
          '<input id="_bdtt_adddef_placeholder" type="text" placeholder="e.g. enter governing law state" style="width:100%;padding:7px 8px;font-size:12px;font-family:inherit;border:1px solid #cbd5e1;border-radius:0;background:#fff;" />' +
        '</div>' +
        // Warning
        '<label style="font-size:10px;color:#475569;font-weight:600;letter-spacing:0.04em;">WARNING <span style="color:#94a3b8;font-weight:500;">(optional, shown to user in Step 1)</span></label>' +
        '<input id="_bdtt_adddef_warning" type="text" placeholder="e.g. Pick carefully — affects clause 5" style="width:100%;padding:7px 8px;font-size:12px;font-family:inherit;border:1px solid #cbd5e1;border-radius:0;background:#fff;" />' +
        // Preview + actions
        '<label style="font-size:10px;color:#475569;font-weight:600;letter-spacing:0.04em;margin-top:4px;">PREVIEW</label>' +
        '<code id="_bdtt_adddef_preview" style="display:block;font-family:monospace;font-size:10px;color:#1565c0;background:#fff;border:1px dashed #cbd5e1;padding:7px 8px;line-height:1.4;word-break:break-all;">{{DEF: …}}</code>' +
        '<button id="_bdtt_adddef_copy" class="btn-platinum" type="button" style="padding:8px 10px;font-size:11px;width:100%;border-radius:0;" disabled>📋 Copy DEF Tag</button>' +
      '</div>';
    document.getElementById("_bdtt_scan_run").onclick = _runScan;
    // Re-paint cached results if we have them — flipping tabs shouldn't
    // wipe a fresh scan the user just ran.
    if (_bdttScanReport) _paintScanResults(_bdttScanReport);
    _wireAddDefBuilder();
  }

  // Add-DEF builder wiring. Listens to all inputs, rebuilds the preview
  // on every change, enables/disables the Copy button based on
  // validity. Name is uppercased + sanitized (letters/digits/_ only;
  // leading digits get a "D" prefix so DEF parsing in engine.js still
  // works). Choices empty → block copy.
  function _wireAddDefBuilder() {
    var nameEl    = document.getElementById("_bdtt_adddef_name");
    var typeEls   = Array.prototype.slice.call(document.getElementsByName("_bdtt_adddef_type"));
    var choicesEl = document.getElementById("_bdtt_adddef_choices");
    var phEl      = document.getElementById("_bdtt_adddef_placeholder");
    var warnEl    = document.getElementById("_bdtt_adddef_warning");
    var prevEl    = document.getElementById("_bdtt_adddef_preview");
    var copyBtn   = document.getElementById("_bdtt_adddef_copy");
    var choiceBlock = document.getElementById("_bdtt_adddef_choice_block");
    var textBlock   = document.getElementById("_bdtt_adddef_text_block");
    if (!nameEl || !copyBtn) return;
    function _selType() {
      var s = typeEls.find(function (r) { return r.checked; });
      return s ? s.value : "choice";
    }
    function _sanitizeName(raw) {
      var s = String(raw || "").trim().toUpperCase().replace(/[^A-Z0-9_]/g, "_").replace(/^_+|_+$/g, "");
      // Engine parses {{DEF:NAME=...}} so the name has to be safely
      // parseable. Leading digits break some Word-XML uses; prefix.
      if (/^[0-9]/.test(s)) s = "D" + s;
      return s;
    }
    function _build() {
      var type = _selType();
      // Toggle visibility of choice vs text input
      if (choiceBlock) choiceBlock.style.display = (type === "choice") ? "flex" : "none";
      if (textBlock)   textBlock.style.display   = (type === "text")   ? "flex" : "none";
      var name = _sanitizeName(nameEl.value);
      // Sync sanitized value back so the user sees what gets used
      if (nameEl.value !== name && document.activeElement !== nameEl) {
        nameEl.value = name;
      }
      var warning = String(warnEl.value || "").trim();
      var tag = "";
      var valid = false;
      if (!name) {
        tag = "{{DEF: …}}";
      } else if (type === "text") {
        var ph = String(phEl.value || "").trim();
        // Text DEFs use the *placeholder form: {{DEF:NAME|*placeholder|warning}}
        // No default here — text inputs always start empty in Step 1.
        var parts = [name];
        var second = "*" + ph;
        parts.push(second);
        if (warning) parts.push(warning);
        tag = "{{DEF:" + parts.join("|") + "}}";
        valid = true; // text def is valid with just a name
      } else {
        // Choice def: {{DEF:NAME=default|opt1,opt2,opt3|warning}}
        var lines = String(choicesEl.value || "")
          .split(/\r?\n/)
          .map(function (s) { return s.trim(); })
          .filter(Boolean);
        if (!lines.length) {
          tag = "{{DEF:" + name + "=|…|" + (warning || "") + "}}";
        } else {
          var def = lines[0];
          var opts = lines.join(",");
          var pieces = [name + "=" + def, opts];
          if (warning) pieces.push(warning);
          tag = "{{DEF:" + pieces.join("|") + "}}";
          valid = true;
        }
      }
      prevEl.textContent = tag;
      copyBtn.disabled = !valid;
    }
    nameEl.oninput = _build;
    choicesEl.oninput = _build;
    phEl.oninput = _build;
    warnEl.oninput = _build;
    typeEls.forEach(function (r) { r.onchange = _build; });
    copyBtn.onclick = function () {
      var tag = prevEl.textContent;
      if (!tag || tag.indexOf("…") !== -1) return;
      _copyText(tag, "def", _sanitizeName(nameEl.value));
    };
    _build();
  }
  function _runScan() {
    var btn = document.getElementById("_bdtt_scan_run");
    var resEl = document.getElementById("_bdtt_scan_results");
    if (btn) { btn.disabled = true; btn.textContent = "⏳ Scanning…"; }
    if (resEl) resEl.innerHTML = '<div style="font-size:11px;color:#64748b;padding:6px 0;">Reading document body…</div>';
    eli.host.runRaw("bd_template_tester:scan_all_tags", function (context) {
      var b = context.document.body;
      // Catch every {{...}} tag in one pass — DEFs go to the def list,
      // IF/ELSEIF feed orphan-detection, counts power the health
      // summary. Single Word.run, one sync.
      var search = b.search("\\{\\{*\\}\\}", { matchWildcards: true });
      search.load("text");
      return context.sync().then(function () {
        return search.items.map(function (r) { return r.text; });
      });
    }).then(function (matches) {
      // Categorize every {{...}} tag in one pass:
      //   • DEFs go to the deduplicated def list (used by copy buttons)
      //   • IF / ELSEIF feed orphan detection (referenced names without
      //     a matching DEF — Step 1 silently drops these)
      //   • Counts power the health summary at the top
      //
      // Same DEF-dedup rules as before: dedupe by normalized raw text,
      // flag conflicting variants under one name, count repeats.
      var counts = { IF: 0, ELSEIF: 0, ELSE: 0, ENDIF: 0, DEF: 0, TITLE: 0, DELETE_LINE: 0, ENTER: 0, key: 0 };
      var seenRaw = {};
      var defs = [];
      var rawsByName = {};
      var ifRefs = {}; // name -> [{kind:"IF"|"ELSEIF", raw}]
      function _extractCondName(condStr) {
        // condStr is e.g. " PARTY_TYPE == Buyer " — strip the operator
        // and trim. Mirrors evalLogicCondition's split logic.
        var s = String(condStr || "");
        var op = s.indexOf("!=") !== -1 ? "!=" : (s.indexOf("==") !== -1 ? "==" : null);
        if (!op) return s.trim();
        return s.split(op)[0].trim();
      }
      (matches || []).forEach(function (raw) {
        var inner = String(raw).replace(/^\{\{|\}\}$/g, "").trim();
        if (inner.indexOf("DEF:") === 0) {
          counts.DEF++;
          var normalized = String(raw).replace(/\s+/g, " ").trim();
          if (seenRaw[normalized]) { seenRaw[normalized].count++; return; }
          var d = _parseDefTag(raw);
          if (!d) return;
          d.normalized = normalized;
          d.count = 1;
          seenRaw[normalized] = d;
          if (!rawsByName[d.name]) rawsByName[d.name] = {};
          rawsByName[d.name][normalized] = true;
          defs.push(d);
        } else if (inner.indexOf("IF:") === 0) {
          counts.IF++;
          var n1 = _extractCondName(inner.substring(3));
          if (n1) { ifRefs[n1] = ifRefs[n1] || []; ifRefs[n1].push({ kind: "IF", raw: raw }); }
        } else if (inner.indexOf("ELSEIF:") === 0) {
          counts.ELSEIF++;
          var n2 = _extractCondName(inner.substring(7));
          if (n2) { ifRefs[n2] = ifRefs[n2] || []; ifRefs[n2].push({ kind: "ELSEIF", raw: raw }); }
        } else if (inner.indexOf("ENDIF") === 0) {
          counts.ENDIF++;
        } else if (inner.indexOf("ELSE") === 0) {
          counts.ELSE++;
        } else if (inner.indexOf("TITLE:") === 0) {
          counts.TITLE++;
        } else if (inner === "DELETE_LINE") {
          counts.DELETE_LINE++;
        } else if (inner === "ENTER") {
          counts.ENTER++;
        } else {
          counts.key++; // bare {{KEY}} substitutions
        }
      });
      // Flag DEFs whose name has >1 distinct variants.
      defs.forEach(function (d) {
        var variants = Object.keys(rawsByName[d.name] || {}).length;
        if (variants > 1) { d.hasConflict = true; d.variantCount = variants; }
      });
      defs.sort(function (a, b) {
        if (a.hasConflict !== b.hasConflict) return a.hasConflict ? -1 : 1;
        return String(a.name).localeCompare(String(b.name));
      });
      // Orphan detection: every name an IF/ELSEIF references that has
      // no DEF. These are template bugs — Step 1 will not surface a
      // dropdown for them and the branch silently fails to evaluate.
      var defNameSet = {};
      defs.forEach(function (d) { defNameSet[d.name] = true; });
      var orphans = [];
      Object.keys(ifRefs).forEach(function (name) {
        if (!defNameSet[name]) {
          orphans.push({ name: name, refs: ifRefs[name] });
        }
      });
      orphans.sort(function (a, b) { return String(a.name).localeCompare(String(b.name)); });

      _bdttScanDefs = defs;
      _bdttScanReport = { counts: counts, defs: defs, orphans: orphans };
      _paintScanResults(_bdttScanReport);
      if (btn) { btn.disabled = false; btn.textContent = "🔄 Re-scan Document"; }
    }).catch(function (err) {
      eli.log.event("tool", "bd_template_tester_scan_failed", { msg: err && err.message });
      if (resEl) resEl.innerHTML = '<div style="font-size:11px;color:#b91c1c;padding:6px 0;">Scan failed: ' + _esc(err && err.message || "unknown") + '</div>';
      if (btn) { btn.disabled = false; btn.textContent = "🔍 Scan Document"; }
    });
  }
  function _parseDefTag(raw) {
    if (!raw) return null;
    // Strip the outer {{ }} delimiters.
    var inner = String(raw).replace(/^\{\{|\}\}$/g, "");
    if (inner.indexOf("DEF:") !== 0) return null;
    // Mirror engine.js _parseLogicDefs format:
    //   DEF:NAME=defaultValue|opt1,opt2,opt3|warning
    // OR DEF:NAME|*placeholder|warning   (text-input form)
    var t = inner.substring(4).trim();
    var parts = t.split("|");
    var defPart    = (parts[0] || "").trim();
    var optionsPart = (parts[1] || "").trim();
    var warning    = parts.length > 2 ? parts.slice(2).join("|").trim() : null;
    var defSplit = defPart.split("=");
    var name = (defSplit[0] || "").trim();
    if (!name) return null;
    var defaultValue = defSplit.length > 1 ? defSplit.slice(1).join("=").trim() : "";
    var isText = optionsPart.charAt(0) === "*";
    var options = isText
      ? []
      : optionsPart.split(",").map(function (o) { return o.trim(); }).filter(Boolean);
    return {
      name: name,
      defaultValue: defaultValue,
      isText: isText,
      options: options,
      warning: warning,
      raw: raw,
    };
  }
  function _paintScanResults(report) {
    var resEl = document.getElementById("_bdtt_scan_results");
    if (!resEl) return;
    // Defensive: callers from earlier sessions may pass an array of
    // defs directly (the old signature). Normalize.
    if (Array.isArray(report)) report = { counts: null, defs: report, orphans: [] };
    var counts = report.counts || {};
    var defs = report.defs || [];
    var orphans = report.orphans || [];
    var totalTags = (counts.IF || 0) + (counts.ELSEIF || 0) + (counts.ELSE || 0) +
                    (counts.ENDIF || 0) + (counts.DEF || 0) + (counts.TITLE || 0) +
                    (counts.DELETE_LINE || 0) + (counts.ENTER || 0) + (counts.key || 0);
    if (!totalTags) {
      resEl.innerHTML =
        '<div style="font-size:11px;color:#64748b;padding:8px 10px;border:1px dashed #cbd5e1;background:#f8fafc;text-align:center;margin-top:6px;">' +
          'No <code style="font-family:monospace;">{{...}}</code> tags found in this document.' +
        '</div>';
      return;
    }
    resEl.innerHTML =
      _renderHealthSummary(counts, defs.length, orphans.length) +
      (orphans.length ? _renderOrphans(orphans) : '') +
      (defs.length
        ? '<div style="font-size:10px;color:#475569;font-weight:600;letter-spacing:0.04em;padding:6px 0 2px;">' +
            defs.length + ' DEF tag' + (defs.length === 1 ? '' : 's') + ' found' +
          '</div>' +
          '<div style="display:flex;flex-direction:column;gap:8px;">' +
            defs.map(_renderDefCard).join("") +
          '</div>'
        : ''
      );
    // Wire pill picks + copy buttons via event delegation on the
    // results container. One listener handles everything.
    resEl.onclick = function (e) {
      // Pill click — update per-card selection, re-render that card.
      var pill = e.target.closest && e.target.closest("[data-bdtt-pick]");
      if (pill) {
        var pName = pill.getAttribute("data-bdtt-name");
        var role  = pill.getAttribute("data-bdtt-pick");
        var idx   = parseInt(pill.getAttribute("data-bdtt-idx"), 10);
        var def = (_bdttScanDefs || []).find(function (d) { return d.name === pName; });
        if (!def) return;
        var sel = _getCardSel(def);
        if (role === "if") sel.ifIdx = idx;
        else if (role === "elseif") sel.elseifIdx = idx;
        // Repaint only this card in place — cheaper than full re-render
        // and keeps scroll position stable.
        var cardEl = pill.closest("[data-bdtt-card]");
        if (cardEl) {
          var hintWasVisible = false;
          var hint = cardEl.querySelector("[data-bdtt-endif-hint]");
          if (hint) hintWasVisible = (hint.style.display !== "none");
          var temp = document.createElement("div");
          temp.innerHTML = _renderDefCard(def);
          var fresh = temp.firstElementChild;
          if (fresh && cardEl.parentNode) {
            cardEl.parentNode.replaceChild(fresh, cardEl);
            // Preserve the ENDIF reminder if it was already shown — the
            // user already saw it once; flipping a pill shouldn't make
            // it disappear.
            if (hintWasVisible) {
              var newHint = fresh.querySelector("[data-bdtt-endif-hint]");
              if (newHint) newHint.style.display = "block";
            }
          }
        }
        return;
      }
      // Copy-button click — same as before.
      var btn = e.target.closest && e.target.closest("[data-bdtt-copy]");
      if (!btn) return;
      var name = btn.getAttribute("data-bdtt-name");
      var kind = btn.getAttribute("data-bdtt-copy");
      var def2 = (_bdttScanDefs || []).find(function (d) { return d.name === name; });
      if (!def2) return;
      var snippet = _renderCopyText(def2, kind);
      if (!snippet) return;
      _copyText(snippet, kind, name);
      if (kind === "if" || kind === "elseif") {
        var card = btn.closest && btn.closest("[data-bdtt-card]");
        var hint2 = card && card.querySelector("[data-bdtt-endif-hint]");
        if (hint2) hint2.style.display = "block";
      }
    };
  }

  // Health summary — IF/ENDIF balance is the critical check (engine
  // misparses an unbalanced template and silently drops branches).
  // ELSE counts are informational, not health-critical, because ELSE
  // without an IF is harmless (just text in the doc).
  function _renderHealthSummary(counts, defCount, orphanCount) {
    var ifN     = counts.IF     || 0;
    var elseifN = counts.ELSEIF || 0;
    var elseN   = counts.ELSE   || 0;
    var endifN  = counts.ENDIF  || 0;
    var titleN  = counts.TITLE  || 0;
    var keyN    = counts.key    || 0;
    var balanced = (ifN === endifN);
    var hasIssue = !balanced || orphanCount > 0;
    var bg = hasIssue ? '#fef3c7' : '#dcfce7';
    var border = hasIssue ? '#fcd34d' : '#86efac';
    var fg = hasIssue ? '#92400e' : '#166534';
    var headerLabel = hasIssue ? '⚠ STRUCTURE ISSUES' : '✓ STRUCTURE OK';
    function _pill(label, n, danger) {
      var pillBg = danger ? '#fee2e2' : '#fff';
      var pillFg = danger ? '#991b1b' : '#0f172a';
      var pillBorder = danger ? '#fca5a5' : '#cbd5e1';
      return '<span style="display:inline-block;padding:2px 7px;font-size:10px;font-weight:700;background:' + pillBg + ';color:' + pillFg + ';border:1px solid ' + pillBorder + ';margin:2px 4px 2px 0;letter-spacing:0.04em;">' +
        _esc(label) + ': <strong>' + n + '</strong>' +
        '</span>';
    }
    var balanceLine = balanced
      ? '<div style="font-size:10px;color:' + fg + ';margin-top:4px;">IF/ENDIF balanced (' + ifN + ' / ' + endifN + ').</div>'
      : '<div style="font-size:10px;color:#991b1b;margin-top:4px;font-weight:700;">⚠ Unbalanced: <strong>' + ifN + '</strong> IF vs <strong>' + endifN + '</strong> ENDIF — branches will not parse correctly.</div>';
    var orphanLine = orphanCount > 0
      ? '<div style="font-size:10px;color:#991b1b;margin-top:2px;font-weight:700;">⚠ ' + orphanCount + ' IF/ELSEIF reference' + (orphanCount === 1 ? '' : 's') + ' with no matching DEF (see below).</div>'
      : '';
    return '<div style="background:' + bg + ';border:1px solid ' + border + ';padding:10px 12px;display:flex;flex-direction:column;gap:2px;">' +
      '<div style="font-size:10px;font-weight:900;letter-spacing:0.08em;color:' + fg + ';">' + headerLabel + '</div>' +
      '<div style="margin-top:4px;">' +
        _pill('IF', ifN, !balanced) +
        _pill('ELSEIF', elseifN, false) +
        _pill('ELSE', elseN, false) +
        _pill('ENDIF', endifN, !balanced) +
        _pill('DEF', defCount, false) +
        (titleN ? _pill('TITLE', titleN, false) : '') +
        (keyN ? _pill('KEY', keyN, false) : '') +
      '</div>' +
      balanceLine +
      orphanLine +
    '</div>';
  }

  // Orphan list — IFs that reference a name with no DEF. Shows the
  // raw tag text so the user can find it in the doc. Doesn't try to
  // suggest fixes; just surfaces the bug.
  function _renderOrphans(orphans) {
    return '<div style="background:#fee2e2;border:1px solid #fca5a5;padding:10px 12px;display:flex;flex-direction:column;gap:6px;">' +
      '<div style="font-size:10px;font-weight:900;letter-spacing:0.08em;color:#991b1b;">⚠ ORPHAN IF REFERENCES</div>' +
      '<div style="font-size:10px;color:#7f1d1d;line-height:1.5;">These names are referenced by <code>IF</code> / <code>ELSEIF</code> but never <code>DEF</code>\'d — Step 1 won\'t render a dropdown for them and the branch will always be false:</div>' +
      orphans.map(function (o) {
        var refLines = o.refs.map(function (r) {
          return '<code style="display:block;font-family:monospace;font-size:10px;color:#7f1d1d;background:rgba(255,255,255,0.5);padding:2px 6px;margin-top:2px;">' + _esc(r.raw) + '</code>';
        }).join("");
        return '<div style="display:flex;flex-direction:column;gap:2px;">' +
          '<div style="font-size:11px;font-weight:700;color:#991b1b;font-family:monospace;">' + _esc(o.name) +
            ' <span style="font-size:9px;color:#7f1d1d;font-weight:600;font-family:inherit;">(' + o.refs.length + ' reference' + (o.refs.length === 1 ? '' : 's') + ')</span>' +
          '</div>' +
          refLines +
        '</div>';
      }).join("") +
    '</div>';
  }
  // Per-card pill selection state. Maps def-name → {ifIdx, elseifIdx}.
  // Defaults: ifIdx = 0 (first choice), elseifIdx = 1 (second choice if
  // it exists, else 0). Persists across re-renders within the same
  // overlay session so user picks survive the "copy IF then click another
  // pill" loop. Cleared by _closeOverlay alongside _bdttScanReport.
  var _bdttCardSelections = {};
  function _getCardSel(d) {
    var sel = _bdttCardSelections[d.name];
    if (!sel) {
      sel = {
        ifIdx: 0,
        elseifIdx: d.options.length >= 2 ? 1 : 0,
      };
      _bdttCardSelections[d.name] = sel;
    }
    return sel;
  }

  function _renderDefCard(d) {
    var typeBadge = d.isText
      ? '<span style="font-size:9px;font-weight:800;letter-spacing:0.06em;padding:2px 6px;background:#fef3c7;color:#92400e;border:1px solid #fcd34d;text-transform:uppercase;">TEXT</span>'
      : '<span style="font-size:9px;font-weight:800;letter-spacing:0.06em;padding:2px 6px;background:#dbeafe;color:#1e40af;border:1px solid #93c5fd;text-transform:uppercase;">' +
          d.options.length + ' choice' + (d.options.length === 1 ? '' : 's') +
        '</span>';

    var defaultLine = d.defaultValue
      ? '<div style="font-size:9px;color:#64748b;letter-spacing:0.04em;">DEFAULT: <strong style="color:#0f172a;font-weight:600;">' + _esc(d.defaultValue) + '</strong></div>'
      : '';

    // Copy buttons. IF/ELSEIF disabled for text defs and when there
    // aren't enough options. The "Variable" copy always works.
    var canIf = !d.isText && d.options.length >= 1;
    var canElseIf = !d.isText && d.options.length >= 2;
    var btnStyle = "padding:5px 8px;font-size:10px;font-weight:700;letter-spacing:0.04em;border:1px solid #cbd5e1;background:#fff;color:#0f172a;cursor:pointer;border-radius:0;flex:1;text-transform:uppercase;";
    var btnDisabledStyle = "padding:5px 8px;font-size:10px;font-weight:700;letter-spacing:0.04em;border:1px solid #e2e8f0;background:#f8fafc;color:#cbd5e1;cursor:not-allowed;border-radius:0;flex:1;text-transform:uppercase;";

    var cardBorder = d.hasConflict ? "2px solid #f59e0b" : "1px solid #cbd5e1";
    var conflictBanner = d.hasConflict
      ? '<div style="font-size:10px;color:#92400e;background:#fef3c7;border:1px solid #fcd34d;padding:4px 8px;line-height:1.4;">' +
          '⚠ This NAME has <strong>' + d.variantCount + '</strong> different definitions in this document. The choices below are for this variant only.' +
        '</div>'
      : '';
    var countPill = d.count > 1
      ? '<span style="font-size:9px;font-weight:700;color:#475569;background:#f1f5f9;border:1px solid #cbd5e1;padding:1px 5px;letter-spacing:0.04em;">×' + d.count + '</span>'
      : '';
    var rawSample = '<div style="font-size:9px;color:#94a3b8;font-family:monospace;line-height:1.3;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="' + _esc(d.normalized || d.raw) + '">' + _esc(d.normalized || d.raw) + '</div>';

    // Pill rows — text defs get a simple "free-text input" note;
    // choice defs get TWO rows of clickable pills (IF row + ELSEIF row
    // when there are ≥2 options). Selected pill is bold-bordered and
    // tinted; clicking another pill in the same row swaps selection.
    // The selected pill in each row is what the IF/ELSEIF copy button
    // uses.
    var sel = canIf ? _getCardSel(d) : null;
    function _pillRow(role) {
      var selectedIdx = sel ? (role === "if" ? sel.ifIdx : sel.elseifIdx) : -1;
      var roleLabel = role === "if"
        ? '<span style="display:inline-block;min-width:50px;font-size:9px;font-weight:900;letter-spacing:0.08em;color:#166534;background:#dcfce7;border:1px solid #86efac;padding:2px 6px;margin-right:6px;">IF =</span>'
        : '<span style="display:inline-block;min-width:50px;font-size:9px;font-weight:900;letter-spacing:0.08em;color:#92400e;background:#fef3c7;border:1px solid #fcd34d;padding:2px 6px;margin-right:6px;">ELSEIF =</span>';
      var pills = d.options.map(function (o, i) {
        var isSelected = (i === selectedIdx);
        var baseBg = role === "if" ? "#dcfce7" : "#fef3c7";
        var baseFg = role === "if" ? "#166534" : "#92400e";
        var baseBorder = role === "if" ? "#86efac" : "#fcd34d";
        var bg = isSelected ? baseBg : "#f8fafc";
        var fg = isSelected ? baseFg : "#475569";
        var border = isSelected ? "2px solid " + baseBorder : "1px solid #cbd5e1";
        var padding = isSelected ? "0 5px" : "1px 6px"; // compensate for thicker border
        var weight = isSelected ? 800 : 600;
        var checkmark = isSelected ? "✓ " : "";
        return '<button type="button" data-bdtt-pick="' + role + '" data-bdtt-name="' + _esc(d.name) + '" data-bdtt-idx="' + i + '" style="display:inline-block;background:' + bg + ';color:' + fg + ';border:' + border + ';padding:' + padding + ';margin:1px 4px 1px 0;font-weight:' + weight + ';font-size:10px;cursor:pointer;font-family:inherit;border-radius:0;letter-spacing:0.02em;">' + checkmark + _esc(o) + '</button>';
      }).join("");
      return '<div style="font-size:10px;line-height:1.7;display:flex;align-items:center;flex-wrap:wrap;">' + roleLabel + pills + '</div>';
    }

    var optionsHtml = d.isText
      ? '<div style="font-size:10px;color:#64748b;font-style:italic;">free-text input</div>'
      : '<div style="display:flex;flex-direction:column;gap:2px;">' +
          (canIf     ? _pillRow("if")     : '') +
          (canElseIf ? _pillRow("elseif") : '') +
        '</div>';

    // Tooltip text for IF/ELSEIF reflects the CURRENT selection.
    var ifChoice     = canIf     ? d.options[sel.ifIdx]     : '';
    var elseifChoice = canElseIf ? d.options[sel.elseifIdx] : '';

    return '' +
      '<div data-bdtt-card="' + _esc(d.name) + '" style="border:' + cardBorder + ';background:#fff;padding:10px 12px;display:flex;flex-direction:column;gap:6px;">' +
        '<div style="display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;">' +
          '<div style="display:flex;align-items:center;gap:6px;min-width:0;">' +
            '<code style="font-family:monospace;font-size:12px;font-weight:700;color:#1565c0;">' + _esc(d.name) + '</code>' +
            countPill +
          '</div>' +
          typeBadge +
        '</div>' +
        conflictBanner +
        rawSample +
        defaultLine +
        optionsHtml +
        (d.warning
          ? '<div style="font-size:10px;color:#92400e;font-style:italic;line-height:1.4;">⚠️ ' + _esc(d.warning) + '</div>'
          : '') +
        '<div style="display:flex;gap:4px;margin-top:2px;">' +
          '<button data-bdtt-copy="var"     data-bdtt-name="' + _esc(d.name) + '" type="button" style="' + btnStyle + '" title="Copy {{' + _esc(d.name) + '}}">📋 Var</button>' +
          (canIf
            ? '<button data-bdtt-copy="if"     data-bdtt-name="' + _esc(d.name) + '" type="button" style="' + btnStyle + '" title="Copy {{IF: ' + _esc(d.name) + ' == ' + _esc(ifChoice) + '}}">📋 IF</button>'
            : '<button disabled type="button" style="' + btnDisabledStyle + '" title="IF requires at least one choice option">📋 IF</button>'
          ) +
          (canElseIf
            ? '<button data-bdtt-copy="elseif" data-bdtt-name="' + _esc(d.name) + '" type="button" style="' + btnStyle + '" title="Copy {{ELSEIF: ' + _esc(d.name) + ' == ' + _esc(elseifChoice) + '}}">📋 ELSEIF</button>'
            : '<button disabled type="button" style="' + btnDisabledStyle + '" title="ELSEIF requires at least two choice options">📋 ELSEIF</button>'
          ) +
        '</div>' +
        '<div data-bdtt-endif-hint style="display:none;font-size:10px;color:#92400e;font-style:italic;background:#fef3c7;border-left:3px solid #f59e0b;padding:5px 8px;margin-top:2px;">' +
          '💡 Don\'t forget to close with <code style="font-family:monospace;font-style:normal;font-weight:700;">{{ENDIF}}</code>.' +
        '</div>' +
      '</div>';
  }
  function _renderCopyText(d, kind) {
    // Build Draft's evalLogicCondition trims on every side of `==` and
    // around the `IF:` prefix, so this spacing is purely cosmetic.
    // Honor per-card selections so clicking a pill changes which value
    // gets baked into the IF/ELSEIF text.
    if (kind === "var") return "{{" + d.name + "}}";
    var sel = _getCardSel(d);
    if (kind === "if") {
      var iv = d.options[sel.ifIdx] || d.options[0] || "";
      return "{{IF: " + d.name + " == " + iv + "}}";
    }
    if (kind === "elseif") {
      var ev = d.options[sel.elseifIdx] || d.options[1] || "";
      return "{{ELSEIF: " + d.name + " == " + ev + "}}";
    }
    return null;
  }
  function _copyText(text, kind, name) {
    var label = kind === "var" ? "Variable"
              : kind === "if" ? "IF"
              : kind === "elseif" ? "ELSEIF"
              : kind === "def" ? "DEF"
              : "Tag";
    function _ok()  { _toast("✅ " + label + " for " + name + " copied", "ok"); }
    function _err() { _toast("Clipboard blocked — text shown in console as window.__bdtt_lastCopy.", "warn"); try { window.__bdtt_lastCopy = text; } catch (_) {} }
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(_ok).catch(function () {
        // Fall back to the textarea/execCommand trick when the iframe
        // sandbox blocks the async API.
        var ta = document.createElement("textarea");
        ta.value = text;
        ta.style.cssText = "position:fixed;left:-9999px;opacity:0";
        document.body.appendChild(ta);
        ta.select();
        try {
          if (document.execCommand("copy")) _ok(); else _err();
        } catch (_) { _err(); }
        document.body.removeChild(ta);
      });
    } else {
      _err();
    }
  }

  // ─── Bottom toggle button — manual on/off ─────────────────────────
  // Always visible until user explicitly dismisses it. No DOM watchers,
  // no auto-hide on navigation. Visibility persists across reloads via
  // the kernel "config" store. To bring back after dismissing: click the
  // tile in the dashboard.
  //
  // Why manual: an auto-show/hide watcher needs MutationObserver on a
  // wide scope (the kernel replaces _eli3_dashboard_root on _goHome, so
  // anything bound to it goes stale) — which means firing on every
  // taskpane DOM mutation. Even rAF-coalesced, that's avoidable overhead
  // when the user is happy clicking a tile to restore.
  var TOGGLE_ID = "_bdtt_toggle_btn";
  var BTN_VIS_KEY = "bd_template_tester_btn_visible";

  function _loadBtnVisible() {
    // Default true — first install shows the button so user knows the
    // tool installed. Subsequent reads honor whatever the user picked.
    return eli.storage.get("config", BTN_VIS_KEY).then(function (row) {
      if (!row) return true;
      return row.value !== false;
    }).catch(function () { return true; });
  }
  function _saveBtnVisible(v) {
    return eli.storage.put("config", { key: BTN_VIS_KEY, value: !!v })
      .catch(function (e) {
        eli.log.event("tool", "bd_template_tester_btn_vis_put_failed", { msg: e && e.message });
      });
  }

  function _injectToggleButton() {
    if (document.getElementById(TOGGLE_ID)) return;
    var btn = document.createElement("button");
    btn.id = TOGGLE_ID;
    btn.type = "button";
    btn.title = "Open Template Tester (× to dismiss)";
    btn.style.cssText = [
      "position:fixed",
      "bottom:42px",
      "right:18px",
      // Below .eli-overlay (z-index 9999) so any dialog covers the
      // button visually.
      "z-index:9000",
      "padding:8px 14px 8px 14px",
      "font-size:11px",
      "font-weight:800",
      "letter-spacing:0.08em",
      "text-transform:uppercase",
      "color:#fff",
      "background:linear-gradient(135deg,#1e3a8a,#1565c0)",
      "border:1px solid #1e3a8a",
      "border-radius:0",
      "cursor:pointer",
      "box-shadow:0 4px 14px rgba(15,23,42,0.32)",
      "font-family:Inter,'Segoe UI',system-ui,sans-serif",
      "display:inline-flex",
      "align-items:center",
      "gap:10px",
    ].join(";") + ";";
    // Label span + dismiss × in one button — clicking the × hides the
    // button without opening the overlay.
    var label = document.createElement("span");
    label.textContent = "🧪 Test";
    var dismiss = document.createElement("span");
    dismiss.id = "_bdtt_dismiss";
    dismiss.textContent = "×";
    dismiss.title = "Hide button (click the dashboard tile to restore)";
    dismiss.style.cssText = [
      "display:inline-flex",
      "align-items:center",
      "justify-content:center",
      "width:16px",
      "height:16px",
      "font-size:16px",
      "font-weight:700",
      "line-height:1",
      "opacity:0.7",
      "border-left:1px solid rgba(255,255,255,0.25)",
      "padding-left:8px",
      "margin-left:-2px",
    ].join(";") + ";";
    btn.appendChild(label);
    btn.appendChild(dismiss);
    btn.onclick = function (e) {
      // Dismiss × → hide + persist. Don't open the overlay in this case.
      if (e.target && e.target.id === "_bdtt_dismiss") {
        e.stopPropagation();
        _hideToggleButton();
        _saveBtnVisible(false);
        _toast("Test button hidden. Click the Template Tester tile to bring it back.", "info");
        return;
      }
      // Main click → open/close overlay.
      if (document.getElementById("_bdtt_overlay")) _closeOverlay();
      else _openOverlay();
    };
    document.body.appendChild(btn);
  }
  function _hideToggleButton() {
    var btn = document.getElementById(TOGGLE_ID);
    if (btn && btn.parentNode) btn.parentNode.removeChild(btn);
  }

  // Initial paint — read persisted state once, inject if visible. No
  // ongoing watchers from here on.
  //
  // Auto-opens the overlay on every load (user explicitly asked: "it
  // should automatically show the dialog until you click test"). The
  // Test button toggles closed; no need to remember per-session "was
  // it dismissed", because dismissing the BUTTON is a separate persist
  // via the × on the button itself.
  _loadBtnVisible().then(function (visible) {
    if (!visible) return;
    _injectToggleButton();
    // Small delay so the kernel finishes its boot-time paint before
    // we layer a draggable overlay on top — avoids a flash where the
    // overlay appears mid-dashboard-mount.
    setTimeout(function () {
      if (document.getElementById(TOGGLE_ID) && !document.getElementById("_bdtt_overlay")) {
        _openOverlay();
      }
    }, 300);
  });

  // ─── Tile click ───────────────────────────────────────────────────
  // Single canonical "restore + open" path. Whether the button was
  // hidden or not, clicking the tile re-shows it AND opens the overlay.
  // This is the documented way to bring the button back after dismiss.
  eli.register({
    tile: {
      app_bd_template_tester: function () {
        _saveBtnVisible(true);
        _injectToggleButton();
        _openOverlay();
      },
    },
  });

  eli.log.event("tool", "bd_template_tester_initialized", { email: userEmail });
}
